<?php namespace App\Http\Controllers; use App\Http\Requests\StoreRoomRequest; use App\Models\{Facility,MeetingRoom}; use Illuminate\Http\Request; use Illuminate\Support\Facades\Storage;
class RoomController extends Controller { public function index(Request $r){$rooms=MeetingRoom::with('facilities')->when($r->search,fn($q,$v)=>$q->where('name','like',"%$v%"))->when($r->location,fn($q,$v)=>$q->where('location',$v))->when($r->capacity,fn($q,$v)=>$q->where('capacity','>=',$v))->paginate(9)->withQueryString(); return view('rooms.index',compact('rooms'));} public function show(MeetingRoom $room){return view('rooms.show',compact('room'));} public function create(){return view('rooms.form',['room'=>new MeetingRoom,'facilities'=>Facility::all()]);} public function store(StoreRoomRequest $r){$d=$r->validated();if($r->hasFile('image'))$d['image_path']=$r->file('image')->store('rooms','public');$room=MeetingRoom::create($d);$room->facilities()->sync($d['facilities']??[]);return redirect()->route('admin.rooms.index')->with('success','Ruangan ditambahkan.');} public function edit(MeetingRoom $room){return view('rooms.form',['room'=>$room->load('facilities'),'facilities'=>Facility::all()]);} public function update(StoreRoomRequest $r,MeetingRoom $room){$d=$r->validated();if($r->hasFile('image')){$d['image_path']=$r->file('image')->store('rooms','public');} $room->update($d);$room->facilities()->sync($d['facilities']??[]);return redirect()->route('admin.rooms.index')->with('success','Ruangan diperbarui.');} }
